def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff:
            degree = n - i
            if coeff < 0:
                terms.append(f'{coeff}x^({degree})')
            else:
                terms.append(f'{coeff}x^{degree}')
    return '+'.join(terms)

