def string_transformation(A, B, rules):
    # Initialize the queue for BFS
    queue = [(A, 0)]
    # Set the max number of steps
    max_steps = 10
    # Define the transformation function
    def transform(s, rule):
        return s.replace(rule[0], rule[1])
    #Iterate over the queue until it is empty or the max steps is reached
    while queue and queue[0][1] <= max_steps:
        # Get the current string and step
        s, step = queue.pop(0)
        # If the current string is the target, return the step
        if s == B:
            return step
        # Iterate over the rules
        for rule in rules:
            # If the rule can be applied, add the new string to the queue
            if rule[0] in s:
                queue.append((transform(s, rule), step + 1))
    # If no answer is found after the max steps, return "NO ANSWER!"
    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    A prime number is a natural number greater than 1 that has no positive divisors other than 1 and itself. The function checks for primality by eliminating non-prime numbers using several tests. First, it handles edge cases for numbers less than or equal to 1, which are not prime, and small numbers (2 and 3) which are prime. It then checks for divisibility by 2 and 3. For larger numbers, it uses a 6k +/- 1 optimization to test for factors up to the square root of the number.

    Args:
        num (int): The integer to check for primality.

    Returns:
        bool: True if `num` is a prime number, False otherwise.
    """
    if num <= 1:
        return False

    if num in {2, 3}:
        return True

    if num % 2 == 0 or num % 3 == 0:
        return False

    for i in range(5, int(num ** 0.5) + 1, 6):
        if num % i == 0 or num % (i + 2) == 0:
            return False

    return True

