def generate_numbers(n, rules):
    queue = [n]  # Breadth-First Search queue
    visited = set(queue)  # Keep track of unique numbers generated

    while queue:
        num = queue.pop(0)  # Dequeue the next number
        for rule in rules:  # Apply all transformation rules
            new_num = 0
            for digit in str(num):
                if digit == rule[0]:
                    new_num = new_num * 10 + rule[1]
                else:
                    new_num = new_num * 10 + digit
            if new_num not in visited:
                queue.append(new_num)
                visited.add(new_num)

    return len(visited)  # Return the total count of unique numbers generated

