    for area in areas:
        # Get the start and end positions of the current area
        start, end = area

        # Check if the current area overlaps with any previously cleared areas
        for cleared_area in cleared_trees:
            # If the current area overlaps with a previously cleared area, merge the two areas
            if start <= cleared_area[1] and end >= cleared_area[0]:
                start = min(start, cleared_area[0])
                end = max(end, cleared_area[1])
                cleared_area[0] = start
                cleared_area[1] = end
                break
