        else:
            cleared_trees.append([start, end])

    # Calculate the number of remaining trees by subtracting the total cleared areas from the road length
    return l - sum(end - start for start, end in cleared_trees)

def min_remaining_space(V, n, volumes):
    # Initialize a 2D table to store the maximum volume that can be occupied
    # in the box by any subset of the first i items, where 0 <= i <= n
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill in the table
    for i in range(1, n + 1):
        for v in range(1, V + 1):
            dp[i][v] = max(dp[i - 1][v], dp[i - 1][v - volumes[i - 1]] + volumes[i - 1])

    # Return the difference between the box's total capacity and the maximum volume that can be occupied
    return V - dp[n][V]

