    if len(key) != len(ciphertext):
        raise ValueError("Key and ciphertext must be the same length")

    # Check that the key only contains alphabetic characters
    if not key.isalpha():
        raise ValueError("Key must consist only of alphabetic characters")

    # Build the decryption dictionary
    decryption_dict = {}
    for i in range(len(key)):
        decryption_dict[key[i]] = chr(ord(key[i]) - ord('A') + ord('Z'))

    # Decrypt the ciphertext using the dictionary
    decrypted_text = ""
    for i in range(len(ciphertext)):
        decrypted_text += decryption_dict[ciphertext[i]]

    return decrypted_text

